-- Revisable migration for Admin > Finanzas. Do not run on existing databases
-- until reviewed and scheduled with a backup.
CREATE TABLE `FinancialPermissionGrant` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `permission` ENUM('FINANCE_READ','FINANCE_MANAGE') NOT NULL, `granted` BOOLEAN NOT NULL DEFAULT true, `grantedById` CHAR(36) NULL, `revokedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `FinancialPermissionGrant_user_permission_key` (`userId`,`permission`), KEY `FinancialPermissionGrant_user_granted_idx` (`userId`,`granted`));
CREATE TABLE `FinancialProvider` (`id` CHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, `kind` ENUM('AWS','GOOGLE_MAPS','RESEND','OTHER') NOT NULL, `currency` VARCHAR(3) NOT NULL DEFAULT 'USD', `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `FinancialProvider_name_key` (`name`));
CREATE TABLE `FinancialService` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NOT NULL, `name` VARCHAR(160) NOT NULL, `sku` VARCHAR(160) NULL, `active` BOOLEAN NOT NULL DEFAULT true, PRIMARY KEY (`id`), UNIQUE KEY `FinancialService_providerId_name_key` (`providerId`,`name`), KEY `FinancialService_providerId_active_idx` (`providerId`,`active`), CONSTRAINT `FinancialService_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `FinancialBudget` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NULL, `name` VARCHAR(160) NOT NULL, `amountCop` DECIMAL(14,2) NOT NULL, `amountUsd` DECIMAL(14,4) NULL, `periodStart` DATE NOT NULL, `periodEnd` DATE NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), KEY `FinancialBudget_period_idx` (`periodStart`,`periodEnd`,`active`), CONSTRAINT `FinancialBudget_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE `FinancialConsumption` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NOT NULL, `serviceId` CHAR(36) NULL, `externalId` VARCHAR(255) NOT NULL, `periodStart` DATE NOT NULL, `periodEnd` DATE NOT NULL, `amountUsd` DECIMAL(14,4) NOT NULL, `amountCop` DECIMAL(14,2) NOT NULL, `creditsUsd` DECIMAL(14,4) NOT NULL DEFAULT 0, `dataKind` ENUM('REAL','ESTIMATED','PROJECTED','MANUAL') NOT NULL, `region` VARCHAR(80) NULL, `metadata` JSON NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `FinancialConsumption_external_key` (`providerId`,`externalId`,`periodStart`,`periodEnd`), KEY `FinancialConsumption_provider_period_idx` (`providerId`,`periodStart`,`periodEnd`), KEY `FinancialConsumption_service_period_idx` (`serviceId`,`periodStart`), CONSTRAINT `FinancialConsumption_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `FinancialConsumption_serviceId_fkey` FOREIGN KEY (`serviceId`) REFERENCES `FinancialService` (`id`) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE `FinancialInvoice` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NOT NULL, `externalId` VARCHAR(255) NOT NULL, `invoiceNumber` VARCHAR(120) NULL, `periodStart` DATE NOT NULL, `periodEnd` DATE NOT NULL, `amountUsd` DECIMAL(14,4) NOT NULL, `amountCop` DECIMAL(14,2) NOT NULL, `dataKind` ENUM('REAL','ESTIMATED','PROJECTED','MANUAL') NOT NULL DEFAULT 'REAL', `documentUrl` VARCHAR(2048) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `FinancialInvoice_external_key` (`providerId`,`externalId`), KEY `FinancialInvoice_period_idx` (`periodStart`,`periodEnd`), CONSTRAINT `FinancialInvoice_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `FinancialPayment` (`id` CHAR(36) NOT NULL, `invoiceId` CHAR(36) NOT NULL, `amountCop` DECIMAL(14,2) NOT NULL, `paidAt` DATETIME(3) NULL, `status` ENUM('PENDING','PAID','CANCELLED') NOT NULL, `reference` VARCHAR(160) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `FinancialPayment_invoice_status_idx` (`invoiceId`,`status`), CONSTRAINT `FinancialPayment_invoiceId_fkey` FOREIGN KEY (`invoiceId`) REFERENCES `FinancialInvoice` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `FinancialCredit` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NOT NULL, `externalId` VARCHAR(255) NOT NULL, `description` VARCHAR(255) NOT NULL, `amountUsd` DECIMAL(14,4) NOT NULL, `expiresAt` DATE NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `FinancialCredit_external_key` (`providerId`,`externalId`), KEY `FinancialCredit_expires_idx` (`expiresAt`), CONSTRAINT `FinancialCredit_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `ExchangeRate` (`id` CHAR(36) NOT NULL, `fromCurrency` VARCHAR(3) NOT NULL, `toCurrency` VARCHAR(3) NOT NULL, `rate` DECIMAL(18,8) NOT NULL, `effectiveAt` DATE NOT NULL, `source` VARCHAR(80) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `ExchangeRate_pair_date_key` (`fromCurrency`,`toCurrency`,`effectiveAt`));
CREATE TABLE `FinancialSyncRun` (`id` CHAR(36) NOT NULL, `providerId` CHAR(36) NOT NULL, `status` ENUM('RUNNING','SUCCEEDED','FAILED') NOT NULL, `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `finishedAt` DATETIME(3) NULL, `attempts` INT NOT NULL DEFAULT 0, `error` TEXT NULL, PRIMARY KEY (`id`), KEY `FinancialSyncRun_provider_started_idx` (`providerId`,`startedAt`), CONSTRAINT `FinancialSyncRun_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `FinancialProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `FinancialAlert` (`id` CHAR(36) NOT NULL, `budgetId` CHAR(36) NULL, `dedupeKey` VARCHAR(255) NOT NULL, `threshold` INT NOT NULL, `message` TEXT NOT NULL, `acknowledgedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `FinancialAlert_dedupeKey_key` (`dedupeKey`), KEY `FinancialAlert_budget_created_idx` (`budgetId`,`createdAt`));
CREATE TABLE `FinancialAuditEntry` (`id` CHAR(36) NOT NULL, `actorUserId` CHAR(36) NULL, `entityType` VARCHAR(80) NOT NULL, `entityId` CHAR(36) NOT NULL, `action` VARCHAR(100) NOT NULL, `beforeState` JSON NULL, `afterState` JSON NULL, `reason` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `FinancialAuditEntry_entity_idx` (`entityType`,`entityId`,`createdAt`), KEY `FinancialAuditEntry_actor_idx` (`actorUserId`,`createdAt`));
